import { defineTool } from "eve/tools";
import { z } from "zod";
import { BROWSER_ID_PATH, stopCloudBrowser } from "../cloud.js";

/**
 * Stops the cloud browser opened by `open_cloud_browser`, ending billing. Reads
 * the browser id the open tool wrote into the sandbox; the stop call itself runs
 * in the app runtime (where the API key lives).
 */
export default defineTool({
  description:
    "Stop the cloud browser and end its billing. Call this when you are finished browsing.",
  inputSchema: z.object({}),
  async execute(_input, ctx) {
    const sandbox = await ctx.getSandbox();
    const { stdout } = await sandbox.run({
      command: `cat /workspace/${BROWSER_ID_PATH} 2>/dev/null || true`,
    });
    const id = stdout.trim();
    if (!id) {
      return { ok: true, note: "No cloud browser was open." };
    }
    await stopCloudBrowser(id);
    await sandbox.run({ command: `rm -f /workspace/${BROWSER_ID_PATH}` });
    return { ok: true, stopped: id };
  },
});

import { defineTool } from "eve/tools";
import { z } from "zod";
import {
  BROWSER_ID_PATH,
  CDP_WS_PATH,
  createCloudBrowser,
  resolveWebSocketUrl,
} from "../cloud.js";

// Connect the persistent harness session to the cloud browser and focus a tab.
// The session lives in the sandbox's long-running browser-harness-js REPL, so a
// single connect carries across the agent's later `browser-harness-js` calls.
function connectSnippet(wsUrl: string): string {
  return [
    `await session.connect({ wsUrl: ${JSON.stringify(wsUrl)} });`,
    `const targets = await listPageTargets();`,
    `if (targets[0]) await session.use(targets[0].targetId);`,
    // Enable the domains the agent relies on so events (e.g. load) are delivered
    // and waitFor() works.
    `await session.Page.enable();`,
    `await session.Runtime.enable();`,
    `"connected";`,
  ].join(" ");
}

/**
 * Provisions a Browser Use cloud browser (in the app runtime, where the API key
 * lives), resolves its WebSocket URL, hands ONLY that URL to the sandbox, and
 * connects the driver. The agent then drives via `browser-harness-js`.
 */
export default defineTool({
  description:
    "Open a cloud browser for web browsing. Call this once before using browser-harness-js. Returns a liveUrl you can share to watch the session.",
  inputSchema: z.object({}),
  async execute(_input, ctx) {
    const { id, cdpUrl, liveUrl } = await createCloudBrowser();
    const wsUrl = await resolveWebSocketUrl(cdpUrl);

    const sandbox = await ctx.getSandbox();
    // Non-secret: a scoped WS endpoint + the browser id (for teardown).
    await sandbox.writeTextFile({ path: CDP_WS_PATH, content: wsUrl });
    await sandbox.writeTextFile({ path: BROWSER_ID_PATH, content: id });

    const { exitCode, stderr } = await sandbox.run({
      command: `source /workspace/.bu-env && browser-harness-js '${connectSnippet(wsUrl)}'`,
    });
    if (exitCode !== 0) {
      throw new Error(`failed to connect the browser driver: ${stderr}`);
    }

    return {
      ok: true,
      liveUrl,
      instructions:
        "Cloud browser ready and connected. Drive it with: source /workspace/.bu-env && browser-harness-js '<async JS using session.*>'. Call stop_cloud_browser when done.",
    };
  },
});

import { defineConfig } from "vitest/config";

export default defineConfig({
  test: {
    environment: "node",
    include: ["test/**/*.test.ts"],
  },
});

import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { EXAMPLE_SNIPPETS } from "../src/skill/index.ts";

// --- Mirror of browser-harness-js sdk/repl.ts output semantics (keep in sync). ---
// The REPL only auto-returns a SINGLE expression (no `;`/newline, not starting
// with a statement keyword); anything else is run without a `return` and yields
// `undefined`. renderResult prints nothing for undefined/""/[]/{}.
function isExpression(code: string): boolean {
  const t = code.trim();
  if (/[;\n]/.test(t)) return false;
  if (/^(let|const|var|if|for|while|do|switch|class|function|throw|try|return|import|export)\b/.test(t)) return false;
  return true;
}
async function runSnippet(code: string): Promise<unknown> {
  const body = isExpression(code) ? `return (${code});` : code;
  const wrapped = `(async () => { ${body} })()`;
  return await (0, eval)(wrapped);
}
function renderResult(s: unknown): string {
  if (s === undefined || s === null) return "";
  if (typeof s === "string") return s;
  if (Array.isArray(s) && s.length === 0) return "";
  if (typeof s === "object" && s !== null && Object.keys(s as object).length === 0) return "";
  return JSON.stringify(s);
}

// Stub the globals the snippets reference (the REPL exposes `session` +
// `listPageTargets`; example placeholders `x`/`y` are coordinates).
beforeAll(() => {
  const g = globalThis as unknown as Record<string, unknown>;
  g.x = 100;
  g.y = 200;
  g.listPageTargets = async () => [{ targetId: "t", title: "x", url: "https://x" }];
  g.session = {
    Page: {
      navigate: async () => ({ frameId: "f" }),
      captureScreenshot: async () => ({ data: "AAAA" }),
      enable: async () => undefined,
    },
    Runtime: {
      evaluate: async () => ({ result: { value: ["a", "b", "c"] } }),
      enable: async () => undefined,
    },
    Input: { dispatchMouseEvent: async () => undefined },
    waitFor: async () => undefined,
    use: async () => "sid",
    connect: async () => undefined,
  };
});
afterAll(() => {
  const g = globalThis as unknown as Record<string, unknown>;
  for (const k of ["x", "y", "listPageTargets", "session"]) delete g[k];
});

describe("skill example snippets", () => {
  it("has examples", () => {
    expect(EXAMPLE_SNIPPETS.length).toBeGreaterThan(0);
  });

  for (const { label, code } of EXAMPLE_SNIPPETS) {
    it(`prints non-empty output: ${label}`, async () => {
      // Structural rule — the 0.0.3 bug was multi-statement (had a `;`).
      expect(isExpression(code), `must be one expression (no ; or newline): ${code}`).toBe(true);
      // Functional rule — actually produces output through the REPL.
      const printed = renderResult(await runSnippet(code));
      expect(printed, `printed empty: ${code}`).not.toBe("");
    });
  }

  it("self-check: the broken 0.0.3 pattern would fail this test", async () => {
    const broken = `(async () => { return JSON.stringify("ping"); })()`;
    expect(isExpression(broken)).toBe(false); // has `;`
    expect(renderResult(await runSnippet(broken))).toBe(""); // yields undefined → empty
  });
});

import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { BrowserUseError } from "browser-use-sdk";

// Mock the Cloud SDK: a BrowserUse instance exposing a `browsers` resource.
// vi.hoisted so the mocks exist when the hoisted vi.mock factory runs.
const { create, get, stop } = vi.hoisted(() => ({
  create: vi.fn(),
  get: vi.fn(),
  stop: vi.fn(),
}));
vi.mock("browser-use-sdk", async (importOriginal) => ({
  ...(await importOriginal<typeof import("browser-use-sdk")>()),
  // A real class so `new BrowserUse({ apiKey })` yields an instance whose
  // `browsers` resource is our spies (vi.fn-as-constructor drops the returned obj).
  BrowserUse: class {
    browsers = { create, get, stop };
  },
}));

import {
  createCloudBrowser,
  resolveWebSocketUrl,
  stopCloudBrowser,
} from "../src/cloud.ts";

beforeEach(() => {
  process.env.BROWSER_USE_API_KEY = "test-key";
  create.mockReset();
  get.mockReset();
  stop.mockReset();
});

describe("resolveWebSocketUrl", () => {
  afterEach(() => vi.unstubAllGlobals());

  it("returns webSocketDebuggerUrl from /json/version", async () => {
    const fetchMock = vi.fn(async () => ({
      ok: true,
      json: async () => ({ webSocketDebuggerUrl: "wss://x/devtools/browser/abc" }),
    }));
    vi.stubGlobal("fetch", fetchMock);
    const ws = await resolveWebSocketUrl("https://id.cdp.browser-use.com");
    expect(ws).toBe("wss://x/devtools/browser/abc");
    expect(fetchMock).toHaveBeenCalledWith("https://id.cdp.browser-use.com/json/version");
  });

  it("strips a trailing slash before appending /json/version", async () => {
    const fetchMock = vi.fn(async () => ({
      ok: true,
      json: async () => ({ webSocketDebuggerUrl: "wss://x" }),
    }));
    vi.stubGlobal("fetch", fetchMock);
    await resolveWebSocketUrl("https://id.cdp.browser-use.com/");
    expect(fetchMock).toHaveBeenCalledWith("https://id.cdp.browser-use.com/json/version");
  });

  it("throws on a non-ok response", async () => {
    vi.stubGlobal("fetch", vi.fn(async () => ({ ok: false, status: 502 })));
    await expect(resolveWebSocketUrl("https://x")).rejects.toThrow(/502/);
  });

  it("throws when webSocketDebuggerUrl is absent", async () => {
    vi.stubGlobal("fetch", vi.fn(async () => ({ ok: true, json: async () => ({}) })));
    await expect(resolveWebSocketUrl("https://x")).rejects.toThrow(/webSocketDebuggerUrl/);
  });
});

describe("createCloudBrowser", () => {
  it("maps id/cdpUrl/liveUrl from the create response", async () => {
    create.mockResolvedValue({ id: "b1", cdpUrl: "https://c", liveUrl: "https://l" });
    const r = await createCloudBrowser();
    expect(r).toEqual({ id: "b1", cdpUrl: "https://c", liveUrl: "https://l" });
  });

  it("polls get() until cdpUrl is available", async () => {
    create.mockResolvedValue({ id: "b2", cdpUrl: null, liveUrl: null });
    get.mockResolvedValue({ id: "b2", cdpUrl: "https://ready", liveUrl: null });
    const r = await createCloudBrowser();
    expect(get).toHaveBeenCalledWith("b2");
    expect(r.cdpUrl).toBe("https://ready");
  }, 10_000);

  it("defaults liveUrl to null", async () => {
    create.mockResolvedValue({ id: "b3", cdpUrl: "https://c" });
    const r = await createCloudBrowser();
    expect(r.liveUrl).toBeNull();
  });
});

describe("stopCloudBrowser", () => {
  it("calls browsers.stop with the id", async () => {
    stop.mockResolvedValue({});
    await stopCloudBrowser("b1");
    expect(stop).toHaveBeenCalledWith("b1");
  });

  it("swallows the SDK's not-found error so teardown is idempotent", async () => {
    stop.mockRejectedValue(new BrowserUseError(404, "Session not found"));
    await expect(stopCloudBrowser("b1")).resolves.toBeUndefined();
  });

  it.each([401, 403, 422, 429, 500, 503])("propagates HTTP %i", async (status) => {
    const error = new BrowserUseError(status, "stop failed");
    stop.mockRejectedValue(error);
    await expect(stopCloudBrowser("b1")).rejects.toBe(error);
  });

  it("propagates transport errors even if they look like a not-found error", async () => {
    const error = Object.assign(new Error("transport failed"), { statusCode: 404 });
    stop.mockRejectedValue(error);
    await expect(stopCloudBrowser("b1")).rejects.toBe(error);
  });

  it("throws before calling the SDK when the API key is missing", async () => {
    delete process.env.BROWSER_USE_API_KEY;
    await expect(stopCloudBrowser("b1")).rejects.toThrow("BROWSER_USE_API_KEY is not set");
    expect(stop).not.toHaveBeenCalled();
  });
});

import { existsSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { HARNESS_FILES, scaffold, ScaffoldError } from "../src/cli/scaffold.ts";

let dir: string;
beforeEach(() => {
  dir = mkdtempSync(join(tmpdir(), "bue-scaffold-"));
});
afterEach(() => {
  rmSync(dir, { recursive: true, force: true });
});

function writePkg(json = "{}"): void {
  writeFileSync(join(dir, "package.json"), json);
}

describe("scaffold", () => {
  it("writes the four thin files", () => {
    writePkg();
    const r = scaffold(dir);
    expect(r.written.sort()).toEqual(Object.keys(HARNESS_FILES).sort());
    for (const f of Object.keys(HARNESS_FILES)) {
      expect(existsSync(join(dir, f))).toBe(true);
    }
    expect(readFileSync(join(dir, "agent/sandbox/sandbox.ts"), "utf8")).toContain(
      "browserUseSandbox",
    );
  });

  it("is idempotent — skips existing files without --force", () => {
    writePkg();
    scaffold(dir);
    const r = scaffold(dir);
    expect(r.written).toEqual([]);
    expect(r.skipped).toHaveLength(4);
  });

  it("overwrites with force", () => {
    writePkg();
    scaffold(dir);
    writeFileSync(join(dir, "agent/sandbox/sandbox.ts"), "// hand-edited");
    const r = scaffold(dir, { force: true });
    expect(r.written).toHaveLength(4);
    expect(readFileSync(join(dir, "agent/sandbox/sandbox.ts"), "utf8")).toContain(
      "browserUseSandbox",
    );
  });

  it("throws ScaffoldError when there is no package.json", () => {
    expect(() => scaffold(dir)).toThrow(ScaffoldError);
  });

  it("reports missing dependency and key", () => {
    writePkg('{"dependencies":{}}');
    const r = scaffold(dir);
    expect(r.missingDep).toBe(true);
    expect(r.missingKey).toBe(true);
  });

  it("clears the nudges when dep + key are present", () => {
    writePkg('{"dependencies":{"@browser_use/eve":"*"}}');
    writeFileSync(join(dir, ".env.local"), "BROWSER_USE_API_KEY=bu_test\n");
    const r = scaffold(dir);
    expect(r.missingDep).toBe(false);
    expect(r.missingKey).toBe(false);
  });
});

import { defineConfig } from "tsup";

export default defineConfig({
  entry: [
    "src/sandbox/index.ts",
    "src/skill/index.ts",
    "src/tools/open-cloud-browser.ts",
    "src/tools/stop-cloud-browser.ts",
    "src/cli/index.ts",
  ],
  format: ["esm"],
  dts: true,
  clean: true,
  target: "node24",
  outDir: "dist",
  // eve + zod are peers, browser-use-sdk is a runtime dep — never bundle them.
  external: ["eve", "zod", "browser-use-sdk"],
});

// App-runtime helpers for the Browser Use cloud browser. These run in eve's app
// runtime (full process.env), NOT in the sandbox, so BROWSER_USE_API_KEY never
// leaves the host. Backed by the official `browser-use-sdk`.
import { BrowserUse, BrowserUseError } from "browser-use-sdk";

const sleep = (ms: number) => new Promise<void>((r) => setTimeout(r, ms));

/** Where the agent's sandbox reads the (non-secret) scoped WS URL and the id. */
export const CDP_WS_PATH = ".bu-cdp";
export const BROWSER_ID_PATH = ".bu-browser-id";

export interface CloudBrowserOptions {
  /** Two-letter country for the Browser Use residential proxy, e.g. "us", "de". */
  proxyCountryCode?: string;
  /** Reuse a saved cloud profile (logged-in cookies) by id. */
  profileId?: string;
}

function client(): BrowserUse {
  const apiKey = [REDACTED];
  if (!apiKey) {
    throw new Error(
      "BROWSER_USE_API_KEY is not set in the app runtime. Add it to .env.local.",
    );
  }
  return new BrowserUse({ apiKey });
}

export interface ProvisionedBrowser {
  id: string;
  cdpUrl: string;
  liveUrl: string | null;
}

/** Create a cloud browser and wait until its cdpUrl is available. */
export async function createCloudBrowser(
  opts: CloudBrowserOptions = {},
): Promise<ProvisionedBrowser> {
  const c = client();
  // The SDK types proxyCountryCode as a country-code enum; our public option is
  // a plain string (validated server-side), so cast to the SDK's body type.
  const body = { ...opts } as Parameters<typeof c.browsers.create>[0];
  let b = await c.browsers.create(body);
  // cdpUrl can be null while the browser is still provisioning.
  for (let i = 0; i < 30 && !b.cdpUrl; i++) {
    await sleep(1000);
    b = await c.browsers.get(b.id);
  }
  if (!b.cdpUrl) {
    throw new Error(`cloud browser ${b.id} did not return a cdpUrl in time`);
  }
  return { id: b.id, cdpUrl: b.cdpUrl, liveUrl: b.liveUrl ?? null };
}

/**
 * browser-harness-js connects with `new WebSocket(wsUrl)`, so it needs a
 * ws/wss browser-level URL — not the HTTPS cdpUrl. Resolve it from the cloud
 * endpoint's /json/version (its `webSocketDebuggerUrl`).
 */
export async function resolveWebSocketUrl(cdpUrl: string): Promise<string> {
  const base = cdpUrl.replace(/\/+$/, "");
  const res = await fetch(`${base}/json/version`);
  if (!res.ok) {
    throw new Error(`GET ${base}/json/version failed: ${res.status}`);
  }
  const info = (await res.json()) as { webSocketDebuggerUrl?: string };
  if (!info.webSocketDebuggerUrl) {
    throw new Error(`no webSocketDebuggerUrl from ${base}/json/version`);
  }
  return info.webSocketDebuggerUrl;
}

/** Stop a cloud browser to end billing. Idempotent-friendly: swallows not-found. */
export async function stopCloudBrowser(id: string): Promise<void> {
  try {
    await client().browsers.stop(id);
  } catch (err) {
    // A browser already stopped/expired should not fail teardown.
    if (!(err instanceof BrowserUseError && err.statusCode === 404)) throw err;
    if (process.env.BROWSER_USE_EVE_DEBUG) console.error("stopCloudBrowser", err);
  }
}

// Pure scaffolding logic — no console, no process.exit — so it's unit-testable.
// The bin (./index.ts) wraps this with argv parsing and output.
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";

/** The harness-mode thin files. Each is a one-liner; logic lives in the package. */
export const HARNESS_FILES: Record<string, string> = {
  "agent/sandbox/sandbox.ts":
    'import { browserUseSandbox } from "@browser_use/eve/sandbox";\nexport default browserUseSandbox();\n',
  "agent/skills/browser-use.ts":
    'export { default } from "@browser_use/eve/skill";\n',
  "agent/tools/open_cloud_browser.ts":
    'export { default } from "@browser_use/eve/tools/open-cloud-browser";\n',
  "agent/tools/stop_cloud_browser.ts":
    'export { default } from "@browser_use/eve/tools/stop-cloud-browser";\n',
};

export class ScaffoldError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "ScaffoldError";
  }
}

export interface ScaffoldResult {
  written: string[];
  skipped: string[];
  missingDep: boolean;
  missingKey: boolean;
}

/**
 * Write the thin files into an eve app at `root`. Skips existing files unless
 * `force`. Throws ScaffoldError if `root` has no package.json.
 */
export function scaffold(root: string, opts: { force?: boolean } = {}): ScaffoldResult {
  const pkgPath = join(root, "package.json");
  if (!existsSync(pkgPath)) {
    throw new ScaffoldError(
      `no package.json in ${root}. Run this from your eve app root, or pass the path.`,
    );
  }

  const written: string[] = [];
  const skipped: string[] = [];
  for (const [rel, content] of Object.entries(HARNESS_FILES)) {
    const abs = join(root, rel);
    if (existsSync(abs) && !opts.force) {
      skipped.push(rel);
      continue;
    }
    mkdirSync(dirname(abs), { recursive: true });
    writeFileSync(abs, content);
    written.push(rel);
  }

  let pkg: { dependencies?: Record<string, string>; devDependencies?: Record<string, string> } = {};
  try {
    pkg = JSON.parse(readFileSync(pkgPath, "utf8"));
  } catch {
    /* ignore malformed package.json — just means we nudge to install */
  }
  const deps = { ...pkg.dependencies, ...pkg.devDependencies };
  const missingDep = !deps["@browser_use/eve"];

  const envPath = join(root, ".env.local");
  const missingKey = !(
    existsSync(envPath) && /^BROWSER_USE_API_KEY=[REDACTED], "utf8"))
  );

  return { written, skipped, missingDep, missingKey };
}

#!/usr/bin/env node
// @browser_use/eve — scaffolds the thin files that wire @browser_use/eve into an
// eve app. Mirrors the ergonomics of `eve channels add <kind>`.
import { resolve } from "node:path";
import { scaffold, ScaffoldError } from "./scaffold.js";

function runAdd(args: string[]): void {
  const force = args.includes("--force");
  const target = args.find((a) => !a.startsWith("--"));
  const root = resolve(target ?? ".");

  let result;
  try {
    result = scaffold(root, { force });
  } catch (err) {
    const msg = err instanceof ScaffoldError ? err.message : String(err);
    console.error(`@browser_use/eve: ${msg}`);
    process.exit(1);
  }

  console.log("\n  @browser_use/eve — cloud browser for your eve agent\n");
  for (const f of result.written) console.log(`  + ${f}`);
  for (const f of result.skipped) console.log(`  · ${f}  (exists — re-run with --force to overwrite)`);

  const next: string[] = [];
  if (result.missingDep) next.push("npm i @browser_use/eve");
  if (result.missingKey) next.push("add BROWSER_USE_API_KEY=bu_... to .env.local");
  if (next.length) {
    console.log("\n  next steps:");
    for (const n of next) console.log(`    - ${n}`);
  }
  console.log("\n  Then ask your agent to browse the web. ✨\n");
}

function main(): void {
  const [cmd, ...rest] = process.argv.slice(2);
  switch (cmd) {
    case "add":
      runAdd(rest);
      break;
    case undefined:
    case "-h":
    case "--help":
      console.log("Usage: @browser_use/eve add [target-dir] [--force]");
      break;
    default:
      console.error(`@browser_use/eve: unknown command "${cmd}". Try: @browser_use/eve add`);
      process.exit(1);
  }
}

main();

import { defineSandbox } from "eve/sandbox";

const HARNESS_REPO = "https://github.com/browser-use/browser-harness-js";

// Sourced before every browser-harness-js call: puts the CLI and Bun on PATH.
// No secret here — the cloud credential never enters the sandbox.
const ENV_FILE = ".bu-env";
const ENV_CONTENT = 'export PATH="$HOME/.local/bin:$HOME/.bun/bin:$PATH"\n';

export interface BrowserUseSandboxOptions {
  /**
   * Override eve's sandbox backend. Defaults to eve's availability-aware
   * backend (Vercel Sandbox in prod; Docker/microsandbox locally).
   */
  backend?: Parameters<typeof defineSandbox>[0]["backend"];
}

/**
 * An eve sandbox preconfigured to drive a Browser Use cloud browser.
 *
 * `bootstrap` (cached per template) installs the TypeScript driver
 * `browser-harness-js` and Bun, and puts both on PATH. Provisioning the actual
 * cloud browser happens lazily in the `open_cloud_browser` tool (app runtime),
 * so the API key never enters the sandbox.
 */
export function browserUseSandbox(opts: BrowserUseSandboxOptions = {}) {
  return defineSandbox({
    ...(opts.backend ? { backend: opts.backend } : {}),
    async bootstrap({ use }) {
      const sb = await use();
      // 1. The raw-CDP TypeScript driver, with its CLI on PATH.
      await sb.run({
        command: `git clone --depth 1 ${HARNESS_REPO} "$HOME/browser-harness-js"`,
      });
      await sb.run({
        command:
          'mkdir -p "$HOME/.local/bin" && ln -sf "$HOME/browser-harness-js/sdk/browser-harness-js" "$HOME/.local/bin/browser-harness-js"',
      });
      // 2. Bun (the driver's REPL is Bun-native). Pre-install so the first
      //    call is fast and deterministic instead of auto-installing live.
      await sb.run({ command: "curl -fsSL https://bun.sh/install | bash" });
      // 3. PATH env file the skill sources before each call.
      await sb.writeTextFile({ path: ENV_FILE, content: ENV_CONTENT });
    },
  });
}

export default browserUseSandbox;

